import {batchRigidDetails} from './rigid-details.js?v=detail18';
import * as T from './three.module.js';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
export const PICKUP_STYLES={touring:{name:'Touring double cab · Amarok-inspired',width:1.99,nose:1.22,grille:1.24,light:.45,roof:1.92},utility:{name:'Utility double cab · Hilux-inspired',width:1.86,nose:1.34,grille:1.04,light:.43,roof:1.84},terrain:{name:'Terrain double cab · Ranger-inspired',width:2.03,nose:1.27,grille:1.38,light:.36,roof:1.94}};
// Original metre-scale hard-surface geometry. No badges or claim of manufacturer-authored assets.
export function pickupGeometry(style='touring'){const spec=PICKUP_STYLES[style]||PICKUP_STYLES.touring,scene=new T.Group(),w=spec.width,parts=[],mats={paint:new T.MeshStandardMaterial({name:'Paint',color:'#789092',metalness:.45,roughness:.28}),dark:new T.MeshStandardMaterial({name:'Dark',color:'#262d30',roughness:.7}),chrome:new T.MeshStandardMaterial({name:'Chrome',color:'#a9b5b9',metalness:.9,roughness:.23}),glass:new T.MeshStandardMaterial({name:'Glass',color:'#5a7887',metalness:.2,roughness:.17}),light:new T.MeshStandardMaterial({name:'lightWhite',color:'#e5eee9',emissive:'#b6d8e1',emissiveIntensity:.35}),red:new T.MeshStandardMaterial({color:'#a83d37',emissive:'#602324',emissiveIntensity:.2}),rubber:new T.MeshStandardMaterial({name:'Rubber',color:'#202526',roughness:.96})};
 function mesh(geo,mat,x,y,z,parent=scene){const o=new T.Mesh(geo,mats[mat]||mat);o.position.set(x,y,z);parent.add(o);if(parent===scene)parts.push(o);return o;}
 const box=(a,b,c,mat,x,y,z,parent=scene)=>mesh(new T.BoxGeometry(a,b,c),mat,x,y,z,parent);
 function section(name,levels,mat){const positions=[],idx=[];for(const [y,width,front,back]of levels)positions.push(-width/2,y,back,width/2,y,back,width/2,y,front,-width/2,y,front);for(let j=0;j<levels.length-1;j++)for(let i=0;i<4;i++){const a=j*4+i,b=j*4+(i+1)%4,c=b+4,d=a+4;idx.push(a,b,c,a,c,d);}idx.push(0,2,1,0,3,2);const n=(levels.length-1)*4;idx.push(n,n+1,n+2,n,n+2,n+3);const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setIndex(idx);g.setAttribute('uv',new T.Float32BufferAttribute(positions.flatMap((v,i)=>i%3===0?[v,positions[i+2]]:[]),2));g.computeVertexNormals();const m=mesh(g,mat,0,0,0);m.name=name;return m;}
 box(w-.12,.22,5.25,'dark',0,.52,0);section('Sculpted lower body',[[.64,w-.13,2.65,-2.7],[.99,w,2.63,-2.68],[1.16,w-.07,2.51,-2.65]],'paint');section('Sloping bonnet',[[1.15,w-.08,2.52,.95],[1.43,w-.16,2.31,.82]],'paint');section('Double cab',[[1.1,w-.08,.96,-1.12],[1.43,w-.12,.91,-1.11],[spec.roof,w-.34,.35,-.89]],'paint');
 // Separate inclined glass panels, pillars and four doors, rather than a box cab.
 const wind=box(w-.47,.61,.025,'glass',0,1.66,.65);wind.rotation.x=.80;const rear=box(w-.48,.39,.023,'glass',0,1.66,-1.0);rear.rotation.x=-.35;
 for(const side of [-1,1]){for(const [z,len]of [[.30,.72],[-.58,.62]]){const glass=box(.025,.39,len,'glass',side*(w/2-.125),1.66,z);glass.rotation.z=side*-.16;box(.045,.05,len+.06,'chrome',side*(w/2-.06),1.43,z);box(.027,.48,.025,'dark',side*(w/2-.027),1.17,z-len/2-.02);box(.11,.045,.17,'dark',side*(w/2+.015),1.32,z-.18);}box(.045,.48,.10,'paint',side*(w/2-.13),1.65,-.13);box(.22,.13,.27,'paint',side*(w/2+.12),1.5,.62);box(.025,.095,.20,'glass',side*(w/2+.238),1.5,.62);box(.10,.10,1.9,'dark',side*(w/2+.07),.65,-.06);box(.17,.04,1.85,'chrome',side*(w/2+.08),.70,-.07);box(.15,.35,1.51,'paint',side*(w/2-.035),1.25,-1.87);box(.19,.045,1.53,'dark',side*(w/2-.035),1.45,-1.87);box(.025,.14,.24,'red',side*(w/2-.04),1.19,-2.708);}
 box(w-.36,.055,1.47,'dark',0,1.1,-1.88);for(let i=0;i<10;i++)box(.045,.025,1.35,'dark',-.73+i*.16,1.14,-1.88);box(w-.12,.33,.13,'paint',0,1.25,-2.64);box(.3,.05,.04,'dark',0,1.39,-2.714);box(w,.20,.20,'chrome',0,.73,-2.72);box(w,.24,.17,'dark',0,.72,2.67);
 const grille=box(spec.grille,.37,.035,'dark',0,1.12,2.64);for(let i=0;i<6;i++)box(spec.grille-.08,.017,.045,i%2?'dark':'chrome',0,.98+i*.055,2.665);for(const side of [-1,1]){box(spec.light,.19,.04,'light',side*(w/2-.29),1.3,2.60);box(.10,.075,.03,'light',side*(w/2-.18),.8,2.77);if(style==='terrain')box(.045,.32,.045,'light',side*(w/2-.10),1.18,2.635);if(style==='utility'){const bar=box(.045,.22,.035,'chrome',side*.5,1.12,2.7);bar.rotation.z=side*-.3;}box(.08,.04,.18,'red',side*.65,.69,-2.84);}
 box(.41,.10,.022,'dark',0,.83,2.774);box(.34,.075,.022,'chrome',0,.83,2.791);box(.42,.09,.025,'dark',0,.85,-2.84);
 // Round tyres, independent axles, alloys, brake discs and tread blocks.
 for(const side of [-1,1])for(const front of [false,true]){const pivot=new T.Group();pivot.name='wheel-'+(front?'front':'rear')+'-'+(side<0?'left':'right');pivot.position.set(side*(w/2-.03),.45,front?1.72:-1.75);scene.add(pivot);const tire=mesh(new T.CylinderGeometry(.45,.45,.29,32), 'rubber',0,0,0,pivot);tire.rotation.z=Math.PI/2;const disc=mesh(new T.CylinderGeometry(.32,.32,.31,24),'dark',0,0,0,pivot);disc.rotation.z=Math.PI/2;for(const a of [-1,1]){const face=mesh(new T.TorusGeometry(.30,.025,6,24),'chrome',a*.16,0,0,pivot);face.rotation.y=Math.PI/2;for(let k=0;k<6;k++){const spoke=box(.035,.045,.49,'chrome',a*.165,0,0,pivot);spoke.rotation.x=k*Math.PI/3;}const hub=mesh(new T.CylinderGeometry(.08,.08,.025,12),'chrome',a*.18,0,0,pivot);hub.rotation.z=Math.PI/2;}const arch=mesh(new T.TorusGeometry(.50,.065,6,24,Math.PI),'dark',side*(w/2+.01),.45,front?1.72:-1.75);arch.rotation.y=Math.PI/2;arch.rotation.z=Math.PI/2;}
 // Merge body by material; wheel assemblies stay articulated.
 scene.updateMatrixWorld(true);const groups=new Map();for(const o of parts){const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);if(!groups.has(o.material))groups.set(o.material,[]);groups.get(o.material).push(g);scene.remove(o);}for(const [m,gs]of groups){scene.add(new T.Mesh(mergeGeometries(gs),m));for(const g of gs)g.dispose();}batchRigidDetails(scene);scene.name=spec.name;scene.userData.bodyStyle=style;return {scene,animations:[]};}
